  ...Interactive.transformSchema,
} as const satisfies InteractivitySchema;

const ELEMENT_PROP_KEYS = new Set(["theme","title","goalLabel","fill","accent","fontFamily","ink","background","scale","delay","grain","speed"]);

const ELEMENT_PROP_DEFAULTS: Record<string, unknown> = {
  theme: "dark",
  title: "This month",
  goalLabel: "of goal",
  fill: 42,
  accent: "#3B5BFD",
  fontFamily: "Sora",
  scale: 1,
  delay: 0,
  grain: true,
  speed: 1,
};

type ActivityRingsElementProps = InteractiveBaseProps &
  InteractiveTransformProps &
  ComponentProps<typeof ActivityRingsBase>;

const ActivityRingsInner = forwardRef<
  HTMLDivElement,
  ActivityRingsElementProps & { readonly controls: SequenceControls | undefined }
>(({ controls, name, style, ...rest }, ref) => {
  const outlineRef = useRef<HTMLDivElement>(null);
  useImperativeHandle(ref, () => outlineRef.current as HTMLDivElement, []);
  const componentProps: Record<string, unknown> = { ...ELEMENT_PROP_DEFAULTS };
  const sequenceProps: Record<string, unknown> = {};
  for (const [key, value] of Object.entries(rest)) {
    if (ELEMENT_PROP_KEYS.has(key)) {
      if (value !== undefined) componentProps[key] = value;
    } else {
      sequenceProps[key] = value;
    }
  }
  return (
    <Sequence
      layout="none"
      {...sequenceProps}
      controls={controls}
      name={name ?? "<ActivityRings>"}
      outlineRef={outlineRef}
    >
      <div
        ref={outlineRef}
        style={{
          position: "relative",
          width: "100%",
          height: "100%",
          display: "flex",
          alignItems: "center",
          justifyContent: "center",
          ...style,
        }}
      >
        <ActivityRingsBase
          {...(componentProps as unknown as ComponentProps<typeof ActivityRingsBase>)}
        />
      </div>
    </Sequence>
  );
});

export const ActivityRings = Interactive.withSchema({
  Component: ActivityRingsInner,
  componentName: "<ActivityRings>",
  componentIdentity: null,
  schema: elementSchema,
  supportsEffects: false,
});
